// A feed mod in one file: the patterns x-timeline is built from, small.
//
//   /feed            a slash command that answers with text (the transcript
//                    keeps it, the model reads it) ...
//   CommandOutput    ... and draws its newest answer live in the chat:
//                    tabs and buttons that work in place
//   Pane             the same drawing in a side pane
//   $.state atoms    what the drawings read; a write redraws them
//   $.tool.register  a read-only tool, so Claude can read what is on screen
//
// Rename `hn-feed` (here, in plugin.json and types/index.d.ts), point
// `load` at your own source, and draw your own rows.
import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register, RenderInput } from 'claude-code'

import type { Feed, Story, Tab } from '../types'

const PANE = 'hn-feed'
const API = 'https://hacker-news.firebaseio.com/v0'
const SHOWN = 10

const EMPTY: Feed = { tab: 'top', stories: [], saved: [], error: null, liveTail: null }
const feed = atom({ plugin: 'hn-feed', key: 'feed' } as const, EMPTY)

type Engine = EngineInterface

// Every function handed `$` is declared at the top of this file: the engine
// reads the module's source to list what it calls, and follows `$` only here.
async function load($: Engine, tab: Tab): Promise<void> {
  try {
    const ids = JSON.parse((await $.http.fetch(`${API}/${tab}stories.json`)).text) as number[]
    const items = await Promise.all(ids.slice(0, SHOWN).map(id => $.http.fetch(`${API}/item/${id}.json`).then(res => JSON.parse(res.text))))
    const stories: Story[] = items.map(item => ({
      id: item.id,
      title: item.title ?? '(untitled)',
      url: item.url ?? null,
      by: item.by ?? '',
      score: item.score ?? 0,
      comments: item.descendants ?? 0,
    }))
    await update($, feed, f => ({ ...EMPTY, ...f, tab, stories, error: null }))
  } catch (error) {
    await update($, feed, f => ({ ...EMPTY, ...f, error: error instanceof Error ? error.message : String(error) }))
  }
}

function asText(f: Feed): string {
  if (f.error) return `⚠ ${f.error}`
  const rows = f.stories.map((story, i) => `\`${i + 1}\` **${story.title}** · ▲${story.score} · 💬${story.comments}${story.url ? `  \n${story.url}` : ''}`)

  return [`**${f.tab === 'top' ? 'Top' : 'New'}** stories`, ...rows].join('\n\n')
}

// The answer `/feed` prints; its tail marks the row the chat draws live.
async function show($: Engine, tab: Tab): Promise<string> {
  await load($, tab)
  const text = asText(await read($, feed))
  await update($, feed, f => ({ ...f, liveTail: text.slice(-120) }))
  void $.ui.open({ id: PANE, title: 'HN' })

  return text
}

function toggleSaved($: Engine, id: number) {
  return update($, feed, f => ({ ...f, saved: f.saved.includes(id) ? f.saved.filter(one => one !== id) : [...f.saved, id] }))
}

// One drawing for both sites; `$.ui.resolve(e)` gives the surface's elements.
async function draw($: Engine, e: RenderInput<'Pane' | 'CommandOutput'>) {
  const { Box, Text, Button, Link } = $.ui.resolve(e)
  const f = await read($, feed)
  const tab = (name: Tab, label: string, hotkey: string) => (
    <Button key={`tab-${name}`} plain hotkey={hotkey} onPress={() => void load($, name)}>
      <Text bold={f.tab === name} underline={f.tab === name} dimColor={f.tab !== name}>
        {label}
      </Text>
    </Button>
  )

  return (
    <Box flexDirection="column">
      <Box columnGap={2}>
        {tab('top', 'Top', '1')}
        {tab('new', 'New', '2')}
      </Box>
      {f.error && <Text color="error">⚠ {f.error}</Text>}
      {f.stories.map(story => (
        <Box key={String(story.id)} flexDirection="column" marginTop={1}>
          <Text bold>{story.title}</Text>
          <Box columnGap={2}>
            <Text dimColor>
              ▲{story.score} · 💬{story.comments} · {story.by}
            </Text>
            <Button key={`save-${story.id}`} plain dimColor={!f.saved.includes(story.id)} onPress={() => void toggleSaved($, story.id)}>
              {f.saved.includes(story.id) ? '★ saved' : '☆ save'}
            </Button>
            {story.url && <Link href={story.url} label="↗" />}
          </Box>
        </Box>
      ))}
    </Box>
  )
}

export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    await $.command.register({ name: 'feed', description: 'Hacker News stories (top | new)', argumentHint: '[top|new]' })
    await $.tool.register({
      name: 'read_feed',
      description: 'Read the stories the hn-feed mod has loaded for the user. Read-only; makes no request.',
      inputSchema: { type: 'object', properties: {} },
    })

    return next(e)
  })

  on('command.run', { command: 'feed' }, async ($, e) => ({ text: await show($, e.args.trim() === 'new' ? 'new' : 'top') }))

  // The tool's arguments ride the event itself; this one takes none.
  on('tool.call', { tool: /^mcp__hn-feed__read_feed$/ }, async $ => {
    const text = asText(await read($, feed))

    return { result: { text }, text }
  })

  on('ui.render', { component: 'Pane', requestId: PANE }, ($, e) => draw($, e))

  // Only the newest `/feed` answer is live; older ones stay the text they were.
  on('ui.render', { component: 'CommandOutput', props: { command: 'feed' } }, async ($, e, next) => {
    const f = await read($, feed)

    return f.liveTail && e.props.text.endsWith(f.liveTail) ? draw($, e) : next(e)
  })
}

