export type Story = { id: number; title: string; url: string | null; by: string; score: number; comments: number }

export type Tab = 'top' | 'new'

export type Feed = { tab: Tab; stories: Story[]; saved: number[]; error: string | null; liveTail: string | null }

declare module 'claude-code' {
  interface PluginState {
    'hn-feed': { feed: Feed }
  }
}
